// Offline support. Install: precache the whole game (app files + the CDN modules it imports), so a
// device that opened it once can fly offline. Fetch: network-first (always fresh when online),
// falling back to the cache offline. The list is generated by `node tools/precache.mjs`.
const CACHE = 'tgs-202611201627';
const PRECACHE = [
 "./",
 "./assets/clouds.mp4",
 "./assets/img/hud.png",
 "./assets/img/icon-192.png",
 "./assets/img/icon-512.png",
 "./assets/img/logo.png",
 "./assets/img/thumb-cobra.png",
 "./assets/img/thumb-cylinder.png",
 "./assets/img/thumb-pea.png",
 "./assets/img/thumb-suturing.jpg",
 "./assets/img/thumb-triangle.png",
 "./assets/models/fenestrated.glb",
 "./assets/models/maryland.glb",
 "./assets/sfx/back.mp3",
 "./assets/sfx/beginDrill.mp3",
 "./assets/sfx/click.mp3",
 "./assets/sfx/error.mp3",
 "./assets/sfx/menuToDrills.mp3",
 "./assets/sfx/startDrill.mp3",
 "./assets/sfx/success.mp3",
 "./assets/sfx/swipe.mp3",
 "./assets/sfx/wind.mp3",
 "./css/campaign.css",
 "./css/school.css",
 "./css/skin.css",
 "./css/style.css",
 "./css/ui.css",
 "./index.html",
 "./js/app.js",
 "./js/audio.js",
 "./js/campaign.js",
 "./js/game/assist.js",
 "./js/game/drills/base.js",
 "./js/game/drills/cobra.js",
 "./js/game/drills/cylinder.js",
 "./js/game/drills/index.js",
 "./js/game/drills/pea.js",
 "./js/game/drills/suturing.js",
 "./js/game/drills/triangle.js",
 "./js/game/engine.js",
 "./js/game/fx.js",
 "./js/game/input.js",
 "./js/game/instruments.js",
 "./js/game/physics.js",
 "./js/game/preview.js",
 "./js/game/session.js",
 "./js/game/themes.js",
 "./js/music.js",
 "./js/progress.js",
 "./js/rules.js",
 "./js/store.js",
 "./js/ui/album.js",
 "./js/ui/buddy.js",
 "./js/ui/controls.js",
 "./js/ui/dom.js",
 "./js/ui/kit.js",
 "./js/ui/mapart.js",
 "./js/ui/panels.js",
 "./js/ui/rewards.js",
 "./js/ui/scorecard.js",
 "./js/ui/screens.js",
 "./manifest.json",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/build/three.module.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/build/three.core.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/environments/RoomEnvironment.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/loaders/GLTFLoader.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/utils/BufferGeometryUtils.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/postprocessing/EffectComposer.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/postprocessing/Pass.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/postprocessing/MaskPass.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/postprocessing/ShaderPass.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/postprocessing/RenderPass.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/postprocessing/OutputPass.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/postprocessing/UnrealBloomPass.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/shaders/CopyShader.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/shaders/LuminosityHighPassShader.js",
 "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/shaders/OutputShader.js",
 "https://cdn.jsdelivr.net/npm/@dimforge/rapier3d-compat@0.14.0/rapier.es.js",
 "https://fonts.googleapis.com/css2?family=Bungee&family=Atkinson+Hyperlegible:wght@400;700&display=swap"
];

self.addEventListener('install', (e) => {
  self.skipWaiting();
  // best effort: one missing file must not block the install
  e.waitUntil(caches.open(CACHE).then((c) => Promise.all(PRECACHE.map((u) => c.add(new Request(u, { mode: u.startsWith('http') ? 'cors' : 'same-origin' })).catch(() => {})))));
});
self.addEventListener('activate', (e) => e.waitUntil(
  caches.keys().then((ks) => Promise.all(ks.filter((k) => k !== CACHE && k.startsWith('tgs-')).map((k) => caches.delete(k)))).then(() => self.clients.claim())));
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || req.headers.has('range')) return; // video range requests go straight to the network
  e.respondWith(fetch(req).then((res) => {
    if (res.ok && (res.type === 'basic' || res.type === 'cors')) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
    return res;
  }).catch(() => caches.match(req, { ignoreSearch: req.mode === 'navigate' }).then((m) => m || caches.match('./'))));
});
